  function overlaps(p){var set={};p.members.forEach(function(m){set[m]=1;});return AL.filter(function(x){return x.id!==p.id;}).map(function(x){var n=x.members.filter(function(m){return set[m];}).length;return{p:x,n:n};}).filter(function(x){return x.n>0;}).sort(function(a,b){return b.n-a.n||a.p.name.localeCompare(b.p.name);}).slice(0,5);}
  function overlapHtml(p){var list=overlaps(p);if(!list.length)return'<div class="alw-instrument"><label>Overlap</label><span>No shared member is present in the tracked register.</span></div>';return'<div class="alw-overlap-table"><div class="alw-overlap-head"><span>Related structure</span><span>Shared</span><span>Share</span><span>Common members</span></div>'+list.map(function(x){var common=x.p.members.filter(function(m){return p.members.indexOf(m)>-1;}),share=Math.round(x.n/Math.max(1,p.memberCount)*100);return'<div class="alw-overlap-row" data-alw-jump="'+esc(x.p.id)+'" title="Open '+esc(x.p.name)+'"><span class="alw-overlap-name">'+esc(x.p.name)+'</span><span class="alw-overlap-count">'+x.n+'</span><span class="alw-overlap-share">'+share+'%</span><span class="alw-overlap-roster" title="'+esc(common.join(', '))+'">'+esc(common.slice(0,4).join(', '))+(common.length>4?' +'+(common.length-4):'')+'</span></div>';}).join('')+'<div class="alw-overlap-note">Share is the percentage of the selected structure\'s roster also present in the related structure. It is a roster calculation, not an influence score.</div></div>';}
  function memberRowsHtml(p){return memberRecords(p).map(function(m,i){return'<details class="alw-member-entry '+(i>9?'alw-member-extra':'')+'" data-alw-member-entry data-alw-country="'+esc(m.country.toLowerCase())+'"><summary class="alw-member-summary"><span class="alw-member-country" title="'+esc(m.country)+'">'+esc(m.country)+'</span><span class="alw-member-standing" title="'+esc(m.standing)+'">'+esc(m.standing)+'</span><span class="alw-member-alignment" data-tone="'+esc(m.tone)+'" title="'+esc(m.alignment)+'">'+esc(m.alignment)+'</span></summary><div class="alw-member-detail"><div><label>Binding / participation basis</label><p>'+esc(m.basis)+'</p></div><div><label>Guideline or vision focus</label><p>'+esc(m.focus)+'</p></div><div class="alw-member-evidence"><label>Recorded adherence evidence</label><p>'+esc(m.evidence)+' <a href="'+esc(m.source)+'" target="_blank" rel="noreferrer">Inspect source ↗</a></p></div></div></details>';}).join('');}
  function membersHtml(p){var s=memberSummary(p);return'<div class="alw-member-method"><div><strong>'+s.aligned+'</strong><span>Recorded alignment</span></div><div><strong>'+s.differentiated+'</strong><span>Differentiated</span></div><div><strong>'+s.transition+'</strong><span>Transition</span></div><div><strong>'+(s.exception+s.review)+'</strong><span>Exception / review</span></div></div><div class="alw-member-tools"><input class="alw-member-search" type="search" aria-label="Search members of '+esc(p.name)+'" placeholder="Find a member country"><span class="alw-member-guide">Open a row for evidence</span></div><div class="alw-member-ledger" data-alw-member-ledger><div class="alw-member-head"><span>Member / participant</span><span>Standing</span><span>Commitment status</span></div>'+memberRowsHtml(p)+'</div>'+(p.memberCount>10?'<button type="button" class="alw-member-expand" data-alw-member-expand>Show all '+p.memberCount+' roster entries</button>':'')+'<div class="alw-overlap-note">Method: “recorded alignment” confirms formal membership and no documented exception in this dossier. It does not claim policy compliance. Differentiated, transition and exception labels require an attributable institutional record.</div>';}
