  function coreHtml(p){return'<div class="alw-facts"><div class="alw-fact"><label>Core purpose</label><strong title="'+esc(p.scope)+'">'+esc(p.scope)+'</strong></div><div class="alw-fact"><label>Binding form</label><strong>'+esc(bindingType(p))+'</strong></div><div class="alw-fact"><label>Decision authority</label><strong title="'+esc(p.decision)+'">'+esc(p.decision)+'</strong></div><div class="alw-fact"><label>Member obligation</label><strong title="'+esc(p.obligation)+'">'+esc(p.obligation)+'</strong></div></div><div class="alw-official"><div class="alw-official-top"><label>Operational vision</label><span class="alw-source">Recorded mandate</span></div><p>'+esc(p.scope)+'. Current implementation focus: '+esc(p.agenda.join('; '))+'.</p></div>';}
  function timelineHtml(p){var rows=[];for(var i=0;i<p.milestones.length;i+=2)rows.push({date:p.milestones[i]||'Recorded',text:p.milestones[i+1]||p.milestones[i]});return'<div class="alw-timeline">'+rows.map(function(x){return'<div class="alw-time"><label>'+esc(x.date)+'</label><p>'+esc(x.text)+'</p></div>';}).join('')+'</div>';}
  function instrumentsHtml(p){var labels=['Current agenda','Institutional instrument','Operational mechanism'];return'<div class="alw-instruments">'+p.agenda.slice(0,3).map(function(x,i){return'<div class="alw-instrument"><label>'+esc(labels[i]||'Agenda')+'</label><span>'+esc(x)+'</span></div>';}).join('')+p.instruments.slice(0,3).map(function(x,i){return'<div class="alw-instrument"><label>'+esc(i===0?'Primary body':i===1?'Mechanism':'Delivery arm')+'</label><span>'+esc(x)+'</span></div>';}).join('')+'</div>';}
  function analyticalBrief(p){var s=memberSummary(p),exceptions=s.exception+s.review;return p.name+' contains '+p.memberCount+' roster entries; '+s.active+' are recorded as active or full participants in this dossier'+(exceptions?', while '+exceptions+' require an exception or status review':' with no formal exception recorded')+'. Decisions operate through '+p.decision.toLowerCase()+', under '+p.legalBasis+'. The latest verified structural development is '+p.latest.charAt(0).toLowerCase()+p.latest.slice(1)+' Monitor next: '+p.next.charAt(0).toLowerCase()+p.next.slice(1);}
  function analyticsHtml(p){var s=memberSummary(p);return'<div class="alw"><header class="alw-head"><i class="alw-mark"></i><div class="alw-headcopy"><h2>'+esc(p.name)+'</h2><p>'+esc(p.short)+' · '+esc(p.region)+' · '+esc(p.category)+'</p></div><span class="alw-status">'+esc(p.status)+'</span></header><section class="alw-section"><div class="alw-sechead"><b>Alliance at a glance</b><span>Source verified '+esc(p.verified)+'</span></div><div class="alw-kpis"><div class="alw-kpi"><label>Roster entries</label><strong>'+p.memberCount+'</strong><span>Countries / institutions</span></div><div class="alw-kpi"><label>Active / full</label><strong>'+s.active+'</strong><span>Excludes formal exception</span></div><div class="alw-kpi"><label>Founded</label><strong>'+esc(p.formed)+'</strong><span title="'+esc(p.seat)+'">'+esc(p.seat)+'</span></div><div class="alw-kpi"><label>Binding form</label><strong>'+esc(bindingType(p))+'</strong><span>'+esc(obligationClass(p))+'</span></div></div><div class="alw-official"><div class="alw-official-top"><label>Latest verified development · '+esc(p.latestDate)+'</label><a class="alw-source" href="'+esc(p.source)+'" target="_blank" rel="noreferrer">'+esc(p.sourceLabel)+' ↗</a></div><p>'+esc(p.latest)+'</p></div></section><section class="alw-section"><div class="alw-sechead"><b>Institutional core</b><span>No inferred scores</span></div>'+coreHtml(p)+'</section><section class="alw-section"><div class="alw-sechead"><b>Member adherence & participation</b><span>Every roster entry · evidence status</span></div>'+membersHtml(p)+'</section><section class="alw-section"><div class="alw-sechead"><b>Membership overlap</b><span>Ranked shared roster</span></div>'+overlapHtml(p)+'</section><section class="alw-section"><div class="alw-sechead"><b>Agenda & operating instruments</b><span>Named mechanisms</span></div>'+instrumentsHtml(p)+'</section><section class="alw-section"><div class="alw-sechead"><b>Structural timeline</b><span>Verified milestones</span></div>'+timelineHtml(p)+'</section><div class="alw-brief"><label>AI analyst brief</label><p>'+esc(analyticalBrief(p))+'</p></div><div class="alw-actions"><button type="button" class="alw-ai" data-alw-research>Research this alliance</button><span class="alw-method">Member ledger, exceptions and official record attach automatically.</span></div></div>';}
